hooks.command:
python3 -c 'import sys,json,re
try:
    d=json.load(sys.stdin)
    t=d.get("tool_name") or ""
    i=d.get("tool_input") or {}
    s=i.get("command") if t=="Bash" else i.get("file_path")
    p=r"(?:/private)?/tmp/claude-[^\s\"|;]*?scratchpad"
    m=re.search(p+r"([^\s\"|;]*)",s or "")
    if m:
        if t=="Bash":
            c=" ".join(re.sub(p,".../scratchpad",s).split())
            v=c[:80]+("..." if len(c)>80 else "")
        else:
            v="..."+m.group(1) if m.group(1).strip("/") else ".../scratchpad"
        print(json.dumps({"systemMessage":"scratchpad: "+t+" "+v}))
except Exception:
    pass
' 2>/dev/null; exit 0
